INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(5840,0,0,'This is... worse... than death...',12,0,100.0,0,0,0,''),
(5840,0,1,'Ugh!  Why are you WET!?',12,0,100.0,0,0,0,''),
(5840,0,2,'Light... fading... dying?  No, just sleeping...',12,0,100.0,0,0,0,''),
(5840,0,3,'Where... did... he... come from...',12,0,100.0,0,0,0,''),
(5840,0,4,'But... but...',12,0,100.0,0,0,0,''),
(5840,0,5,'That\'s... one... giant... keester...',12,0,100.0,0,0,0,''),
(5840,0,6,'Why did it have to be... a smelly ogre...',12,0,100.0,0,0,0,''),
(5840,0,7,'I can\'t feel my legs...',12,0,100.0,0,0,0,''),
(8419,0,0,'Excellent, fresh blood has arrived.',12,0,100.0,20,0,0,'Twilight Idolater'),
(8419,0,1,'You will make a fitting sacrifice to Ragnaros.',12,0,100.0,20,0,0,'Twilight Idolater'),
(8419,0,2,'Infidels!',12,0,100.0,20,0,0,'Twilight Idolater'),
(8419,0,3,'Excellent, fresh blood has arrived.',12,0,100.0,0,0,0,'Twilight Idolater'),
(8421,0,0,'Fools, I knew that if I played upon my brother\'s feeble emotions, he would send \'rescuers.\'',12,0,100.0,0,0,0,'Dorius'),
(8421,1,0,'How easy it was to manipulate you into recovering the last Suntara stone from those imbeciles of the Twilight\'s Hammer.',12,0,100.0,0,0,0,'Dorius'),
(8421,2,0,'When I stumbled upon the Suntara stones at the Grimesilt Digsite, the power of Ragnaros surged through my being. It was Ragnaros that gave me a purpose.',12,0,100.0,0,0,0,'Dorius'),
(8421,3,0,'It was the will of Ragnaros that Obsidion be built. Obsidion will destroy the Blackrock orcs of Blackrock Spire, uniting us with our bretheren in the fiery depths.',12,0,100.0,0,0,0,'Dorius'),
(8421,4,0,'And ultimately, it was Ragnaros that named me when I was reborn as an acolyte of fire: Lathoric... Lathoric the Black.',12,0,100.0,0,0,0,'Dorius'),
(8421,5,0,'%s\'s laughter trails off...',16,0,100.0,0,0,0,'Dorius'),
(8421,6,0,'Bravo! Bravo! Good show. What? You thought I was dead?',12,0,100.0,0,0,0,'Dorius'),
(14627,0,0,'Now that\'s what ye call heavy hands!',14,0,100.0,0,0,0,'Hansel Heavyhands'),
(14636,0,0,'Thieves! Scallywags! Rapscallions! Come face me gigantic pillas!',14,0,100.0,0,0,0,'Chambermaid Pillaclencher'),
(26214,0,0,'You will not stop the Frost Lord from entering this world, mortal. The Tidehunter\'s might will crush that of Ragnaros once and for all, leaving your land a frozen paradise!',12,0,100.0,1,2000,0,'Frigid Lieutenant intro speech'),
(32820,0,0,'Turkey Hunter!',42,0,100.0,0,0,0,'Wild Turkey'),
(32820,1,0,'Turkey Domination!',42,0,100.0,0,0,0,'Wild Turkey'),
(32820,2,0,'Turkey Slaughter!',42,0,100.0,0,0,0,'Wild Turkey'),
(32820,3,0,'TURKEY TRIUMPH!',42,0,100.0,0,0,0,'Wild Turkey'),
(47266,0,0,'Let\'s see what this ember does... whaaaa?',12,0,100.0,0,0,0,'Jack Rockleg'),
(47269,0,0,'Why you do that?  Why you kill?',14,0,100.0,15,0,0,'Lunk'),
(47270,0,0,'%s becomes enraged!',16,0,100.0,0,0,0,'combat Enrage'),
(47270,1,0,'%s becomes enraged!',16,0,100.0,0,0,0,'Gravius Grimesilt'),
(47271,0,0,'What in hell\'s name is going on out here?',14,0,100.0,0,0,0,'Dig-Boss Dinwhisker'),
(47271,1,0,'So you\'re the ones causing all that ruckus!',14,0,100.0,0,0,0,'Dig-Boss Dinwhisker'),
(47309,0,0,'You will suffer!  You will face the wrath of the Twilight\'s Hammer!',12,0,100.0,0,0,0,'Minister Kiyuubi'),
(47310,0,0,'Only pain awaits you!',12,0,100.0,1,0,0,'Minister Letherio'),
(47462,0,0,'The flames of Ragnaros will burn you all.',14,0,100.0,0,0,0,'Archduke Calcinder'),
(47462,1,0,'%s is weakened!  Banish him now!',41,0,100.0,0,0,0,'Archduke Calcinder'),
(47462,2,0,'Fools!  You cannot defeat me!  I will only return again...',14,0,100.0,0,0,0,'Archduke Calcinder');
